```typescript
import * as pulumi from "@pulumi/pulumi";
import * as ripe_atlas from "@supabase/ripe-atlas";

const dnsCanary = new ripe_atlas.Measurement("dns_canary", {
    name: "dns-canary",
    target: "canary.example.com",
    msmType: "dns",
    af: 4,
    cohorts: [
        {
            name: "high-freq",
            probeCount: 30,
            maxProbesPerCell: 1,
            intervalSeconds: 60,
            includeProbeIds: [1001],
            excludeProbeIds: [9999],
            cfg: {
                excludeTags: [
                    "broken",
                    "system-flakey-connection",
                ],
                asn: {
                    "7018": 10,
                    "7922": 8,
                },
                tags: {
                    office: 5,
                    fibre: 2,
                },
                stability: {
                    "system-ipv4-stable-90d": 5,
                },
            },
        },
        {
            name: "low-freq",
            probeCount: 100,
            maxProbesPerCell: 2,
            intervalSeconds: 3600,
            cfg: {
                excludeTags: ["broken"],
                h3Resolution: 5,
            },
        },
    ],
});
const httpCheck = new ripe_atlas.Measurement("http_check", {
    name: "http-check",
    target: "api.example.com",
    msmType: "http",
    af: 4,
    httpMethod: "HEAD",
    httpPath: "/health",
    cohorts: [{
        name: "global",
        probeCount: 50,
        maxProbesPerCell: 2,
        intervalSeconds: 300,
    }],
});
export const msmIds = dnsCanary.cohorts.apply(cohorts => cohorts.map(c => (c.msmId)));
export const probeIds = dnsCanary.cohorts.apply(cohorts => cohorts.map(c => (c.probeIds)));
export const creditBurn = {
    hourly: dnsCanary.totalHourlyCredits,
    daily: dnsCanary.totalDailyCredits,
};
